def is_prime(num):
    """Helper function to check if a number is prime."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_Of_Primes(n):
    """Function to find the sum of prime numbers between 1 and n."""
    prime_sum = 0
    for num in range(2, n + 1):
        if is_prime(num):
            prime_sum += num
    return prime_sum

# Example usage:
n = 30
print(f"The sum of prime numbers between 1 and {n} is: {sum_Of_Primes(n)}")
