def group_element(tuples_list):
    grouped_dict = {}
    for tup in tuples_list:
        if len(tup) != 2:
            raise ValueError("Each tuple must contain exactly two elements.")
        first_element, second_element = tup
        if second_element not in grouped_dict:
            grouped_dict[second_element] = []
        grouped_dict[second_element].append(first_element)
    return grouped_dict

# Example usage:
tuples_list = [
    ('a', 1),
    ('b', 2),
    ('c', 1),
    ('d', 3),
    ('e', 2)
]

result = group_element(tuples_list)
print(result)  # Output: {1: ['a', 'c'], 2: ['b', 'e'], 3: ['d']}
```

