def last_Two_Digits(n):
    if n >= 10:
        return 0
    elif n == 0 or n == 1:
        return 1
    else:
        factorial = 1
        for i in range(2, n + 1):
            factorial = (factorial * i) % 100
        return factorial

# Example usage:
