def divisible_by_digits(start, end):
    def is_divisible_by_digits(n):
        if n == 0:
            return False
        digits = [int(d) for d in str(n)]
        for digit in digits:
            if digit == 0 or n % digit != 0:
                return False
        return True

    result = []
    for number in range(start, end + 1):
        if is_divisible_by_digits(number):
            result.append(number)
    return result

