def second_frequent(sequence):
    if len(sequence) < 2:
        return None  # Not enough elements to have a second most frequent string

    # Dictionary to store the frequency of each string
    frequency = {}

    # Count the frequency of each string in the sequence
    for item in sequence:
        if item in frequency:
            frequency[item] += 1
        else:
            frequency[item] = 1

    # If there is only one unique string, return None
    if len(frequency) < 2:
        return None

    # Sort the frequency dictionary by values in descending order
    sorted_frequency = sorted(frequency.items(), key=lambda x: x[1], reverse=True)

    # Return the second most frequent string
    return sorted_frequency[1][0]

# Example usage:
sequence = ["apple", "banana", "apple", "orange", "banana", "apple"]
print(second_frequent(sequence))  # Output: "banana"
```

