print(is_Isomorphic("foo", "bar"))  # Output: False
print(is_Isomorphic("paper", "title"))  # Output: True
print(is_Isomorphic("abc", "def"))  # Output: True
print(is_Isomorphic("abc", "aabbcc"))  # Output: False
