from functools import reduce

def lcm(a, b):
    """Calculate the Least Common Multiple of two numbers."""
    return a * b // gcd(a, b)

def smallest_multiple(n):
    """Find the smallest multiple of the first n numbers."""
    return reduce(lcm, range(1, n + 1))

