def add_dict(dict1, dict2):
    """
    Combines two dictionaries by adding values for common keys.

    Parameters:
    dict1 (dict): The first dictionary.
    dict2 (dict): The second dictionary.

    Returns:
    dict: A new dictionary with combined values for common keys.
    """
    result = dict1.copy()  # Start with a copy of the first dictionary

    for key, value in dict2.items():
        if key in result:
            result[key] += value  # Add the value from the second dictionary to the existing value
        else:
            result[key] = value  # If the key is not in the result, add it with the value from the second dictionary

    return result

# Example usage:
dict1 = {'a': 1, 'b': 2, 'c': 3}
dict2 = {'b': 3, 'c': 4, 'd': 5}
combined_dict = add_dict(dict1, dict2)
print(combined_dict)  # Output: {'a': 1, 'b': 5, 'c': 7, 'd': 5}
