def process_operations(operations):
    stack = []
    results = []

    for op in operations:
        parts = op.split()
        command = parts[0]

        if command == "Push":
            value = int(parts[1])
            stack.append(value)
        elif command == "Pop":
            if stack:
                stack.pop()
        elif command == "Top":
            if stack:
                results.append(stack[-1])

    return results

# Example usage:
operations = ["Push 1", "Push 2", "Top", "Pop", "Top"]
print(process_operations(operations))  # Output: [2, 1]
